public void processData(ReadableByteChannel channel) throws IOException {
    ByteBuffer buffer = ByteBuffer.allocate(1024);
    try {
        while (channel.read(buffer) != -1) {
            buffer.flip();
            // Process data without knowing if it came from a Socket or File
            buffer.clear();
        }
    } catch (IOException e) {
        // Abstraction of the failure allows for uniform error logging
        logger.error("Failed to process channel data", e);
        throw new DataProcessingException("Critical I/O failure", e);
    }
}
